Tool response:
Tool: find_eligible_tutors
Description: Find tutors meeting specific criteria.
Parameters:
    {
      "type": "object",
      "properties": {
        "certification_names": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "title": "Certification Names",
          "description": ""
        },
        "subject_names": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "title": "Subject Names",
          "description": ""
        },
        "grade_levels": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "title": "Grade Levels",
          "description": ""
        },
        "availability_days": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "integer"
              }
            },
            {
              "type": "null"
            }
          ],
          "title": "Availability Days",
          "description": ""
        },
        "session_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": "after_school",
          "title": "Session Type",
          "description": ""
        },
        "waitlist_active": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "title": "Waitlist Active",
          "description": ""
        }
      },
      "required": []
    }
